/**
 * world.ts — "The Pink Prison Cell" visual world (17 beats / 17 stages)
 * src/videos/pink/world.ts
 *
 * Generated by Claude in browser, adapted for local engine signatures.
 *
 * Usage (in the Remotion composition's three.js scene):
 *   const world = new PinkWorld();  scene.add(world.root);
 *   per frame:  updatePinkCamera(cam, f);  const focus = world.update(f, cam);  lensblur.focus = focus;
 *
 * RULES THIS FILE FOLLOWS
 *  - Pure function of `frame`: nothing accumulates between frames (20 render runners
 *    render slices out of order). No Math.random, no Date, no dt.
 *  - No canvas text / digits / barcodes anywhere (the "Programmatic UI" trap).
 *    Props are broad colour blocks, rolled rims, and engine textures.
 *  - LIGHTS / TONE are driven by shot.light per frame via LIGHTS preset.
 *  - Portrait 9:16: at 2.4 m the frame is only ~0.9 m wide, so every hero prop
 *    and actor is clustered inside |x| < 0.45 around the camera target.
 */
import * as THREE from "three";
import {
  twoTone,
  rep,
  planks,
  brick,
  stone,
  metalPlates,
  tiles,
  cinderblock,
  pinkCellWall,
  glass,
  Actor,
  type CharacterSpec,
  buildPrisonCorridor,
  LIGHTS,
} from "../../engine";
import { shotAt, type PinkShotDef } from "./story";

type V3 = [number, number, number];

/* ════════════════════════════════════════════════════════════════════════════
 * ADAPTER — ENGINE SIGNATURE BRIDGES
 * ════════════════════════════════════════════════════════════════════════════ */
const _mat = new Map<string, THREE.Material>();

function makeMat(
  src: string | THREE.Texture,
  opts: any = {}
): THREE.MeshLambertMaterial {
  const { metal, rough, ...rest } = opts;
  if (typeof src === "string") {
    return twoTone(new THREE.MeshLambertMaterial({ color: src, ...rest }));
  } else {
    return twoTone(new THREE.MeshLambertMaterial({ map: src, ...rest }));
  }
}
const makeMaterial = makeMat;

function solid(hex: string, o: { metal?: boolean; rough?: number } = {}): THREE.Material {
  const k = `solid|${hex}|${o.metal ? 1 : 0}|${o.rough ?? ""}`;
  if (!_mat.has(k)) _mat.set(k, makeMat(hex, o));
  return _mat.get(k)!;
}

function surf(
  key: string,
  make: () => THREE.Texture,
  rx = 1,
  ry = 1,
  o: object = {}
): THREE.Material {
  const k = `surf|${key}|${rx}|${ry}|${JSON.stringify(o)}`;
  if (!_mat.has(k)) _mat.set(k, makeMat(rep(make(), rx, ry), o));
  return _mat.get(k)!;
}

const glow = (hex: string, opacity = 1, additive = false) =>
  new THREE.MeshBasicMaterial({
    color: hex,
    transparent: opacity < 1 || additive,
    opacity,
    depthWrite: !additive,
    blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
    side: THREE.DoubleSide,
  });

function buildPrisonCorridorWrapper(): THREE.Group {
  const g = new THREE.Group();
  buildPrisonCorridor(g, 3.8, 14, 3.2);
  return g;
}

class ActorWrapper extends THREE.Group {
  actor: Actor;
  rotZ: number = 0;

  constructor(parent: THREE.Object3D, spec: CharacterSpec, key: string) {
    super();
    parent.add(this);
    this.actor = new Actor(this);
    this.actor.updateDrawing(spec, key);
  }

  updateSpec(spec: CharacterSpec, key: string) {
    this.actor.updateDrawing(spec, key);
  }

  setPose(rotY = 0, rotZ = 0, scale = 1) {
    this.rotZ = rotZ;
    this.rotation.set(0, rotY, 0);
    this.scale.setScalar(scale);
  }

  faceCamera(camera: THREE.Camera) {
    this.actor.lookAtCamera(camera);
    if (this.rotZ) {
      this.actor.mesh.rotateZ(this.rotZ);
    }
  }
}

/* ── palette (lit surfaces L* >= 72, saturated) ─────────────────────────── */
const INK = "#241726";
const PAL = {
  pink: "#ff7eb6",
  wrong: "#ff9b6b",
  pinkLt: "#ffc6de",
  oak: "#d9964f",
  blue: "#3b8bf0",
  tin: "#e6eaf0",
  steel: "#c9d1dc",
  white: "#fbfbf7",
  red: "#ff5a5f",
  brass: "#f2c14e",
  chalk: "#f7f3e8",
  board: "#7ccaa5",
  orange: "#ff9a3c",
  yellow: "#ffd94a",
  green: "#6fe0a0",
  moon: "#fff6c9",
  skin: "#f4c9a0",
};

/* ── tiny math / easing (all pure) ──────────────────────────────────────── */
const clamp01 = (x: number) => Math.min(1, Math.max(0, x));
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const ease = (t: number) => {
  t = clamp01(t);
  return t * t * (3 - 2 * t);
};
const easeOut = (t: number) => 1 - Math.pow(1 - clamp01(t), 3);
const backOut = (t: number) => {
  t = clamp01(t);
  const c = 1.9;
  return 1 + (c + 1) * Math.pow(t - 1, 3) + c * Math.pow(t - 1, 2);
};
const hash = (n: number) => {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
};

/* ── geometry helpers ───────────────────────────────────────────────────── */
const box = (w: number, h: number, d: number, m: THREE.Material) =>
  new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
const cyl = (rt: number, rb: number, h: number, m: THREE.Material, seg = 32) =>
  new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), m);
const ball = (r: number, m: THREE.Material) =>
  new THREE.Mesh(new THREE.SphereGeometry(r, 24, 16), m);
/** Rolled rim: a flat torus (axis = y) used on every can / beaker / tray / railing end. */
const rim = (r: number, tube: number, m: THREE.Material) => {
  const o = new THREE.Mesh(new THREE.TorusGeometry(r, tube, 10, 40), m);
  o.rotation.x = Math.PI / 2;
  return o;
};
const at = <T extends THREE.Object3D>(o: T, x: number, y: number, z: number) => {
  o.position.set(x, y, z);
  return o;
};

/** Rounded, bevelled slab: w×h in XY, d deep in Z, centred. Bevel gives the "rolled" edge. */
function rbox(w: number, h: number, d: number, r: number, m: THREE.Material) {
  const x = -w / 2,
    y = -h / 2,
    s = new THREE.Shape();
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y);
  s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r);
  s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h);
  s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  const bev = Math.min(r * 0.6, d * 0.3),
    depth = Math.max(0.001, d - 2 * bev);
  const g = new THREE.ExtrudeGeometry(s, {
    depth,
    bevelEnabled: true,
    bevelThickness: bev,
    bevelSize: bev * 0.8,
    bevelSegments: 3,
    curveSegments: 8,
  });
  g.translate(0, 0, -depth / 2);
  return new THREE.Mesh(g, m);
}
/** Flat tray/plate lying on a surface (rbox rotated so its thin axis is y). */
const flatSlab = (w: number, dz: number, th: number, r: number, m: THREE.Material) => {
  const o = rbox(w, dz, th, r, m);
  o.rotation.x = -Math.PI / 2;
  return o;
};

function canvasTex(
  w: number,
  h: number,
  draw: (c: CanvasRenderingContext2D, w: number, h: number) => void
) {
  const cv = document.createElement("canvas");
  cv.width = w;
  cv.height = h;
  draw(cv.getContext("2d")!, w, h);
  const t = new THREE.CanvasTexture(cv);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 8;
  return t;
}

/** Orient a unit-height cylinder so it spans a→b (pour streams, pointers, yarn strands). */
const _up = new THREE.Vector3(0, 1, 0),
  _d = new THREE.Vector3();
function stretch(m: THREE.Object3D, a: THREE.Vector3, b: THREE.Vector3) {
  _d.subVectors(b, a);
  const len = Math.max(1e-4, _d.length());
  m.position.copy(a).addScaledVector(_d, 0.5);
  m.scale.set(1, len, 1);
  m.quaternion.setFromUnitVectors(_up, _d.multiplyScalar(1 / len));
}
const unitCyl = (r: number, m: THREE.Material) => cyl(r, r, 1, m, 12);

/* ════════════════════════════════════════════════════════════════════════════
 * PROP BUILDERS
 * ════════════════════════════════════════════════════════════════════════════ */

/** Gallon / pint paint can: tin body, two rolled rims, label colour block, bail handle. */
function paintCan(r: number, h: number, label: string, paintMat: THREE.Material) {
  const g = new THREE.Group(),
    tin = solid(PAL.tin, { metal: true });
  g.add(at(cyl(r, r, h, tin), 0, h / 2, 0));
  g.add(at(cyl(r * 1.015, r * 1.015, h * 0.5, solid(label)), 0, h * 0.5, 0));
  for (const y of [0.01, h]) g.add(at(rim(r, r * 0.07, tin), 0, y, 0));
  const paint = at(cyl(r * 0.93, r * 0.93, 0.006, paintMat), 0, h - 0.012, 0);
  g.add(paint);
  const bail = new THREE.Mesh(
    new THREE.TorusGeometry(r * 1.02, r * 0.035, 8, 32, Math.PI),
    solid("#8a93a0", { metal: true })
  );
  bail.position.y = h;
  g.add(bail);
  g.userData.paint = paint;
  return g;
}

/** Lab beaker: glass wall, rolled lip, liquid, graduation ticks (plain bars, no numbers). */
function beaker(liquid: string) {
  const g = new THREE.Group();
  const gm = makeMaterial(rep(glass(), 1, 1) as any, {
    transparent: true,
    opacity: 0.38,
  } as any) as THREE.Material;
  g.add(at(cyl(0.058, 0.052, 0.17, gm), 0, 0.085, 0));
  const lq = at(cyl(0.05, 0.047, 0.1, solid(liquid)), 0, 0.055, 0);
  g.add(lq);
  g.add(at(rim(0.058, 0.007, gm), 0, 0.17, 0));
  for (let i = 0; i < 4; i++)
    g.add(at(box(0.03, 0.006, 0.004, solid(INK)), 0, 0.05 + i * 0.03, 0.057));
  g.userData.liquid = lq;
  return g;
}

/** Caged ceiling lamp (corridor, cell). */
function cageLamp() {
  const g = new THREE.Group(),
    st = solid("#9aa3b0", { metal: true });
  g.add(at(cyl(0.12, 0.12, 0.05, st), 0, 0.12, 0));
  const bulb = ball(0.09, glow("#fff4b8"));
  g.add(bulb);
  for (const rx of [0, Math.PI / 3, -Math.PI / 3]) {
    const r = new THREE.Mesh(new THREE.TorusGeometry(0.13, 0.008, 6, 24), st);
    r.rotation.y = rx;
    g.add(r);
  }
  g.add(rim(0.13, 0.012, st));
  g.userData.bulb = bulb;
  return g;
}

/** Steel cell door: frame, hinged leaf (pivot), barred window, pink room glimpse, key ring. */
function buildCellDoor() {
  const g = new THREE.Group(),
    steel = solid(PAL.steel, { metal: true });
  const frameM = surf("plates", metalPlates, 1, 1);
  g.add(at(box(0.1, 2.3, 0.2, frameM), -0.55, 1.15, 0));
  g.add(at(box(0.1, 2.3, 0.2, frameM), 0.55, 1.15, 0));
  g.add(at(box(1.2, 0.1, 0.2, frameM), 0, 2.3, 0));
  // pink room seen through the opening when the door swings
  const pinkBack = canvasTex(64, 128, (c, w, h) => {
    const gr = c.createRadialGradient(w / 2, h * 0.45, 4, w / 2, h * 0.5, h * 0.7);
    gr.addColorStop(0, PAL.pinkLt);
    gr.addColorStop(1, PAL.pink);
    c.fillStyle = gr;
    c.fillRect(0, 0, w, h);
  });
  g.add(
    at(
      new THREE.Mesh(
        new THREE.PlaneGeometry(1.0, 2.2),
        new THREE.MeshBasicMaterial({ map: pinkBack })
      ),
      0,
      1.1,
      -0.3
    )
  );
  const pivot = new THREE.Group();
  pivot.position.set(-0.5, 0, 0.02);
  g.add(pivot);
  pivot.add(at(rbox(0.98, 2.2, 0.08, 0.03, surf("plates", metalPlates, 1, 1)), 0.49, 1.1, 0));
  pivot.add(at(rbox(0.34, 0.26, 0.04, 0.03, solid("#3a2a40")), 0.49, 1.65, 0.05)); // window inset
  for (let i = 0; i < 3; i++)
    pivot.add(at(cyl(0.012, 0.012, 0.26, steel, 8), 0.4 + i * 0.09, 1.65, 0.075));
  pivot.add(at(rbox(0.16, 0.12, 0.05, 0.02, solid(PAL.brass, { metal: true })), 0.82, 1.05, 0.06)); // lock
  for (const y of [0.4, 1.1, 1.8]) {
    const h = cyl(0.04, 0.04, 0.12, steel, 16);
    h.position.set(0.0, y, 0.03);
    pivot.add(h);
    pivot.add(at(rim(0.04, 0.008, steel), 0, y + 0.06, 0.03));
  }
  const keys = new THREE.Group();
  keys.position.set(0.7, 1.0, 0.08);
  pivot.add(keys);
  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(0.05, 0.008, 8, 24),
    solid(PAL.brass, { metal: true })
  );
  keys.add(ring);
  for (let i = 0; i < 3; i++)
    keys.add(
      at(
        box(0.025, 0.09, 0.008, solid(PAL.brass, { metal: true })),
        -0.04 + i * 0.04,
        -0.1,
        0
      )
    );
  return { group: g, pivot, keys };
}

/** Giant stylised stopwatch: rolled rim, white face, 12 tick bars, red sweeping wedge. */
function bigStopwatch() {
  const g = new THREE.Group(),
    brass = solid(PAL.brass, { metal: true });
  g.add(at(cyl(0.3, 0.3, 0.09, brass), 0, 0, 0)).rotation.x = Math.PI / 2;
  const face = new THREE.Group();
  g.add(face);
  const rimT = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.035, 12, 48), brass);
  face.add(at(rimT, 0, 0, 0.05));
  face.add(at(new THREE.Mesh(new THREE.CircleGeometry(0.28, 48), solid(PAL.white)), 0, 0, 0.052));
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2,
      tk = box(0.018, i % 3 === 0 ? 0.06 : 0.035, 0.01, solid(INK));
    tk.position.set(Math.sin(a) * 0.23, Math.cos(a) * 0.23, 0.06);
    tk.rotation.z = -a;
    face.add(tk);
  }
  const wedge = new THREE.Mesh(
    new THREE.CircleGeometry(0.2, 32, Math.PI / 2, 0.01),
    glow(PAL.red)
  );
  wedge.position.z = 0.058;
  face.add(wedge);
  face.add(at(cyl(0.05, 0.05, 0.1, brass, 16), 0, 0.38, 0));
  face.add(at(rim(0.05, 0.012, brass), 0, 0.43, 0));
  g.userData.wedge = wedge;
  return g;
}
function setWedge(g: THREE.Group, frac: number) {
  const w = g.userData.wedge as THREE.Mesh;
  w.geometry.dispose();
  w.geometry = new THREE.CircleGeometry(
    0.2,
    32,
    Math.PI / 2 - frac * Math.PI * 2,
    Math.max(0.01, frac * Math.PI * 2)
  );
}

/** Geometric "?" (torus arc + stem + dot). No font. */
function questionMark() {
  const g = new THREE.Group(),
    m = solid(PAL.yellow);
  const arc = new THREE.Mesh(
    new THREE.TorusGeometry(0.11, 0.035, 12, 32, Math.PI * 1.5),
    m
  );
  arc.rotation.z = -Math.PI / 2;
  g.add(arc);
  g.add(at(cyl(0.035, 0.035, 0.09, m, 12), 0, -0.155, 0));
  g.add(at(ball(0.04, m), 0, -0.27, 0));
  return g;
}

/** 8-point impact star (extruded + bevel) with an ink twin behind it. */
function impactStar(r: number) {
  const g = new THREE.Group(),
    s = new THREE.Shape();
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2,
      rr = i % 2 ? r * 0.55 : r;
    i ? s.lineTo(Math.cos(a) * rr, Math.sin(a) * rr) : s.moveTo(rr, 0);
  }
  s.closePath();
  const geo = new THREE.ExtrudeGeometry(s, {
    depth: 0.02,
    bevelEnabled: true,
    bevelSize: 0.02,
    bevelThickness: 0.01,
    bevelSegments: 2,
  });
  g.add(new THREE.Mesh(geo, solid(PAL.yellow)));
  const back = new THREE.Mesh(geo, solid(INK));
  back.scale.setScalar(1.12);
  back.position.z = -0.03;
  g.add(back);
  return g;
}

/** Wipe-reveal paint panel. fromLeft: pivot on the left edge (scale.x reveals rightwards); else right edge. */
function wipePanel(w: number, h: number, m: THREE.Material, fromLeft: boolean) {
  const geo = new THREE.PlaneGeometry(w, h);
  geo.translate(fromLeft ? w / 2 : -w / 2, 0, 0);
  const mesh = new THREE.Mesh(geo, m);
  mesh.position.x = fromLeft ? -w / 2 : w / 2;
  return mesh;
}
function setWipe(p: THREE.Mesh, reveal: number) {
  const r = clamp01(reveal);
  p.visible = r > 0.002;
  p.scale.x = Math.max(r, 0.001);
}

/** Swatch fan: 5 pink chips on a ring. Chip 0 = wrong shade, chip 4 = correct. */
function swatchFan() {
  const g = new THREE.Group(),
    cols = [PAL.wrong, "#ff9d86", "#ff8aa0", "#ff84ad", PAL.pink];
  g.add(at(cyl(0.025, 0.025, 0.02, solid(PAL.steel, { metal: true }), 12), 0, 0, 0)).rotation.x =
    Math.PI / 2;
  cols.forEach((c, i) => {
    const chip = new THREE.Group();
    chip.rotation.z = -0.25 + i * 0.2;
    chip.add(at(rbox(0.13, 0.36, 0.012, 0.02, solid(INK)), 0, 0.18, -0.006));
    chip.add(at(rbox(0.115, 0.34, 0.014, 0.02, solid(c)), 0, 0.18, 0));
    chip.add(at(rbox(0.115, 0.06, 0.016, 0.01, solid(PAL.white)), 0, 0.03, 0.002));
    g.add(chip);
  });
  return g;
}

/** Puff pool: soft white spheres that grow-then-shrink (no per-frame state). */
function makePuffs(n: number) {
  const g = new THREE.Group(),
    m = glow("#fff0f6", 0.9);
  for (let i = 0; i < n; i++) g.add(ball(0.12, m));
  return g;
}
function animatePuffs(g: THREE.Group, s: number, origin: V3, radius: number) {
  g.visible = s >= 0 && s < 36;
  g.children.forEach((c, i) => {
    const a = (i / g.children.length) * Math.PI * 2 + hash(i) * 0.6,
      k = clamp01(s / 30);
    c.position.set(
      origin[0] + Math.cos(a) * radius * easeOut(k),
      origin[1] + 0.08 + 0.18 * k * (0.5 + hash(i + 3)),
      origin[2] + Math.sin(a) * radius * easeOut(k) * 0.6
    );
    c.scale.setScalar(Math.max(0.001, Math.sin(Math.PI * k) * (0.7 + hash(i + 9) * 0.6)));
  });
}

/** Ribbon (cartoon knitted scarf): flat band following a centre-line fn, updated per frame. */
class Ribbon {
  mesh: THREE.Mesh;
  private pos: Float32Array;
  private attr: THREE.BufferAttribute;
  constructor(private segs: number, private width: number, m: THREE.Material) {
    const g = new THREE.BufferGeometry(),
      n = (segs + 1) * 2;
    this.pos = new Float32Array(n * 3);
    const uv = new Float32Array(n * 2),
      nor = new Float32Array(n * 3),
      idx: number[] = [];
    for (let i = 0; i <= segs; i++) {
      uv.set([(i / segs) * 6, 0, (i / segs) * 6, 1], i * 4);
      nor.set([0, 0, 1, 0, 0, 1], i * 6);
      if (i < segs) {
        const a = i * 2;
        idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
      }
    }
    this.attr = new THREE.BufferAttribute(this.pos, 3);
    g.setAttribute("position", this.attr);
    g.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
    g.setAttribute("normal", new THREE.BufferAttribute(nor, 3));
    g.setIndex(idx);
    this.mesh = new THREE.Mesh(g, m);
    this.mesh.frustumCulled = false;
    (m as any).side = THREE.DoubleSide;
  }
  set(fn: (u: number) => V3) {
    for (let i = 0; i <= this.segs; i++) {
      const u = i / this.segs,
        c = fn(u),
        c2 = fn(Math.min(1, u + 0.01)),
        c0 = fn(Math.max(0, u - 0.01));
      let tx = c2[0] - c0[0],
        ty = c2[1] - c0[1];
      const l = Math.hypot(tx, ty) || 1;
      tx /= l;
      ty /= l;
      const nx = (-ty * this.width) / 2,
        ny = (tx * this.width) / 2;
      this.pos.set([c[0] + nx, c[1] + ny, c[2], c[0] - nx, c[1] - ny, c[2]], i * 6);
    }
    this.attr.needsUpdate = true;
  }
}

