/** Head-centre height for a 3.5 HH actor (1000 u = 2.16 m → head centre ≈ 1.85 m). Used for autofocus. */
const FACE = 1.8;

type StageId = PinkShotDef["stage"];
type SetId = "corridor" | "lab" | "cell" | "pod" | "station" | "classroom" | "yard";

const SET_OF: Record<StageId, SetId> = {
  corridor: "corridor",
  guards_corridor: "corridor",
  stopwatch_rule: "corridor",
  cell_door: "corridor",
  door_exit: "corridor",
  reaction: "corridor",
  mix_bench: "lab",
  paint_wall: "cell",
  pink_cell_inmate: "cell",
  night_quiet: "cell",
  night_pacing: "cell",
  bench_rage: "cell",
  rage_payoff: "cell",
  arm_wrestle: "pod",
  truckload_montage: "yard",
  night_station: "station",
  blackboard_chart: "classroom",
};
/** Cell stages that look at the cell from OUTSIDE the bars (none: every cell shot is interior). */
const BARS_VISIBLE = new Set<StageId>();

/* ════════════════════════════════════════════════════════════════════════════
 * THE WORLD
 * ════════════════════════════════════════════════════════════════════════════ */
export class PinkWorld {
  readonly root = new THREE.Group();
  private sets = {} as Record<SetId, THREE.Group>;
  private actors = new Map<string, { node: ActorWrapper; key: string }>();
  private focus = new THREE.Vector3(0, 1.3, 0);
  private warned = new Set<number>();

  private dirLight: THREE.DirectionalLight;
  private hemiLight: THREE.HemisphereLight;

  // refs filled by the builders
  private C: any = {}; // corridor
  private L: any = {}; // lab
  private K: any = {}; // cell
  private P: any = {}; // pod
  private S: any = {}; // station
  private B: any = {}; // classroom (blackboard)
  private Y: any = {}; // yard

  constructor() {
    this.root.name = "pinkWorld";

    // Lighting rig (driven by LIGHTS[shot.light] in update)
    this.dirLight = new THREE.DirectionalLight("#fff4e0", 3.0);
    this.dirLight.castShadow = true;
    this.dirLight.shadow.mapSize.width = 2048;
    this.dirLight.shadow.mapSize.height = 2048;
    this.dirLight.shadow.bias = -0.0003;
    this.root.add(this.dirLight);

    this.hemiLight = new THREE.HemisphereLight("#9bb8d9", "#2b3038", 0.6);
    this.root.add(this.hemiLight);

    const add = (id: SetId, g: THREE.Group) => {
      g.name = id;
      g.visible = false;
      this.sets[id] = g;
      this.root.add(g);
    };
    add("corridor", this.buildCorridor());
    add("lab", this.buildLab());
    add("cell", this.buildCell());
    add("pod", this.buildPod());
    add("station", this.buildStation());
    add("classroom", this.buildClassroom());
    add("yard", this.buildYard());
  }

  /* ── actors ─────────────────────────────────────────────────────────────── */
  setActorSpec(
    id: string,
    spec: CharacterSpec,
    pos: V3,
    o: { rotY?: number; rotZ?: number; scale?: number } = {}
  ) {
    const key = JSON.stringify(spec);
    let e = this.actors.get(id);
    if (!e) {
      const node = new ActorWrapper(this.root, spec, key);
      e = { node, key };
      this.actors.set(id, e);
    } else if (e.key !== key) {
      e.key = key;
      e.node.updateSpec(spec, key);
    }
    e.node.visible = true;
    e.node.position.set(pos[0], pos[1], pos[2]);
    e.node.setPose(o.rotY ?? 0, o.rotZ ?? 0, o.scale ?? 1);
  }

  /* ════════════════════════════ SET BUILDERS ═══════════════════════════════ */

  private buildCorridor() {
    const g = new THREE.Group();
    g.add(buildPrisonCorridorWrapper());
    this.C.lamps = [0, 1, 2, 3].map((i) => {
      const l = cageLamp();
      l.position.set(0, 2.7, 1.4 - i * 2.2);
      g.add(l);
      return l;
    });
    const door = buildCellDoor();
    g.add(door.group);
    this.C.door = door;
    this.C.splats = new THREE.Group();
    g.add(this.C.splats);
    for (let i = 0; i < 6; i++) {
      const s = new THREE.Mesh(
        new THREE.CircleGeometry(0.1 + hash(i) * 0.08, 20),
        solid(PAL.pink)
      );
      s.rotation.x = -Math.PI / 2;
      s.scale.y = 0.6 + hash(i + 4) * 0.5;
      s.position.set((hash(i + 8) - 0.5) * 0.7, 0.015, 1.2 - i * 0.42);
      this.C.splats.add(s);
    }
    this.C.bucket = at(paintCan(0.14, 0.26, PAL.pink, solid(PAL.pink)), 0.05, 0, 0.45);
    g.add(this.C.bucket);
    this.C.watch = at(bigStopwatch(), 0.45, 1.45, -0.35);
    g.add(this.C.watch);
    this.C.qm = at(questionMark(), 0, 2.0, 0.1);
    g.add(this.C.qm);
    this.C.drops = [0, 1, 2].map((i) => {
      const d = ball(0.03, solid("#8fd4ff"));
      g.add(d);
      return d;
    });
    return g;
  }

  private buildLab() {
    const g = new THREE.Group(),
      wood = surf("planks", planks, 2, 1),
      steel = solid(PAL.steel, { metal: true });
    // room shell
    g.add(at(box(5, 0.1, 4, surf("planks", planks, 4, 3)), 0, -0.05, 0));
    g.add(at(box(5, 3, 0.1, surf("brick", brick, 3, 1.6)), 0, 1.5, -1.25));
    g.add(at(box(0.1, 3, 4, surf("brick", brick, 2, 1.6)), -2.5, 1.5, 0));
    // craftsman oak workbench
    const bench = new THREE.Group();
    g.add(bench);
    bench.add(at(rbox(1.5, 0.7, 0.09, 0.03, wood), 0, 0.92, 0)).rotation.x = -Math.PI / 2;
    bench.add(at(cyl(0.045, 0.045, 1.5, wood, 20), 0, 0.92, 0.35)).rotation.z = Math.PI / 2; // rolled front edge
    for (const [x, z] of [
      [-0.68, -0.28],
      [0.68, -0.28],
      [-0.68, 0.28],
      [0.68, 0.28],
    ])
      bench.add(at(box(0.1, 0.88, 0.1, wood), x, 0.44, z));
    bench.add(at(box(1.4, 0.08, 0.1, wood), 0, 0.7, 0.28));
    bench.add(at(box(1.4, 0.08, 0.1, wood), 0, 0.7, -0.28));
    bench.add(at(box(1.4, 0.04, 0.6, wood), 0, 0.28, 0));
    bench.add(at(box(0.16, 0.12, 0.14, steel), -0.78, 1.0, 0.1)); // vise
    // digital scale (plain blocks) with the gallon can sitting on it
    const sc = new THREE.Group();
    sc.position.set(0, 0.96, 0.05);
    bench.add(sc);
    sc.add(at(rbox(0.34, 0.07, 0.3, 0.02, solid(PAL.steel, { metal: true })), 0, 0.035, 0)).rotation.x = 0;
    sc.add(at(cyl(0.13, 0.13, 0.02, steel), 0, 0.08, 0));
    sc.add(at(rim(0.13, 0.008, steel), 0, 0.09, 0));
    sc.add(at(rbox(0.2, 0.04, 0.02, 0.01, solid("#2a2030")), 0, 0.04, 0.155));
    const bar = at(box(0.17, 0.02, 0.012, glow(PAL.green)), 0, 0.04, 0.168);
    sc.add(bar);
    this.L.bar = bar;
    // gallon can + pint of red + beaker
    this.L.paintMat = makeMaterial(PAL.white as any, {} as any) as THREE.Material;
    const can = paintCan(0.12, 0.22, PAL.blue, this.L.paintMat);
    can.position.set(0, 0.09, 0);
    sc.add(can);
    this.L.can = can;
    this.L.pint = new THREE.Group();
    this.L.pint.add(paintCan(0.05, 0.09, PAL.red, solid(PAL.red)));
    bench.add(this.L.pint);
    const bk = beaker(PAL.pinkLt);
    bk.position.set(0.28, 0.96, 0.12);
    bench.add(bk);
    this.L.beaker = bk;
    this.L.stream = unitCyl(0.012, solid(PAL.red));
    bench.add(this.L.stream);
    this.L.stick = at(cyl(0.008, 0.008, 0.3, wood, 8), 0, 1.3, 0.05);
    bench.add(this.L.stick);
    this.L.bench = bench;
    // shelf of jars on the back wall (blurred background colour)
    g.add(at(box(2.4, 0.05, 0.25, wood), 0.2, 1.7, -1.1));
    [
      "#ff7eb6",
      "#6fe0a0",
      "#ffd94a",
      "#7cb8ff",
      "#ff9a3c",
      "#c79bff",
      "#ff7eb6",
    ].forEach((c, i) => {
      const j = new THREE.Group(),
        jm = solid(c);
      j.add(at(cyl(0.07, 0.07, 0.2, jm), 0, 0.1, 0));
      j.add(at(rim(0.07, 0.012, solid(PAL.tin, { metal: true })), 0, 0.2, 0));
      j.position.set(-0.85 + i * 0.35, 1.725, -1.1);
      g.add(j);
    });
    // window + sunbeams + dust motes
    const win = new THREE.Group();
    win.position.set(-1.0, 2.0, -1.18);
    g.add(win);
    win.add(new THREE.Mesh(new THREE.PlaneGeometry(0.7, 0.9), glow("#fff8d6")));
    for (const [w, h, x, y] of [
      [0.8, 0.06, 0, 0.48],
      [0.8, 0.06, 0, -0.48],
      [0.06, 1.0, -0.38, 0],
      [0.06, 1.0, 0.38, 0],
      [0.04, 0.9, 0, 0],
      [0.7, 0.04, 0, 0],
    ])
      win.add(at(box(w, h, 0.06, solid(PAL.white)), x, y, 0.03));
    const from = new THREE.Vector3(-1.0, 2.0, -1.1),
      to = new THREE.Vector3(0.15, 0.95, 0.15);
    this.L.beams = [0, 1].map((i) => {
      const b = sunbeam(
        from.clone().add(new THREE.Vector3(i * 0.28 - 0.1, -i * 0.25, 0)),
        to.clone().add(new THREE.Vector3(i * 0.2 - 0.1, 0, 0)),
        0.22 - i * 0.05
      );
      g.add(b);
      return b;
    });
    const mg = new THREE.BufferGeometry();
    this.L.motePos = new Float32Array(36 * 3);
    mg.setAttribute("position", new THREE.BufferAttribute(this.L.motePos, 3));
    this.L.motes = new THREE.Points(
      mg,
      new THREE.PointsMaterial({
        color: "#fff6c9",
        size: 0.025,
        transparent: true,
        opacity: 0.8,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      })
    );
    this.L.motes.frustumCulled = false;
    g.add(this.L.motes);
    this.L.splash = at(cyl(0.05, 0.05, 0.004, solid(PAL.red)), 0, 1.22, 0.05);
    sc.parent!.add(this.L.splash);
    return g;
  }

  private buildCell() {
    const g = new THREE.Group(),
      K = this.K,
      W = 3.2,
      H = 2.8;
    g.add(at(box(W + 0.3, 0.1, 3.0, surf("tiles", tiles, 3, 3)), 0, -0.05, 0.4));
    g.add(at(box(W, H, 0.1, surf("cinder", cinderblock, 3, 2)), 0, H / 2, -1.05));
    g.add(at(box(0.1, H, 3.0, surf("pinkwall", pinkCellWall, 2, 1)), -1.65, H / 2, 0.4));
    g.add(at(box(0.1, H, 3.0, surf("pinkwall", pinkCellWall, 2, 1)), 1.65, H / 2, 0.4));
    g.add(at(box(W + 0.3, 0.1, 3.0, surf("plates", metalPlates, 3, 2)), 0, H + 0.05, 0.4));
    const lamp = cageLamp();
    lamp.position.set(0, H - 0.1, 0.2);
    g.add(lamp);
    K.lamp = lamp;
    // two-pass repaint overlays on the back wall
    K.wrong = at(wipePanel(W, H, solid(PAL.wrong), true), -W / 2, H / 2, -0.995);
    K.right = at(wipePanel(W, H, solid(PAL.pink), false), W / 2, H / 2, -0.99);
    K.wrong.position.x = -W / 2;
    K.right.position.x = W / 2;
    g.add(K.wrong, K.right);
    // front bars — named so the director can hide them when the camera is inside
    const bars = new THREE.Group();
    bars.name = "frontBars";
    bars.position.z = 1.8;
    g.add(bars);
    const st = solid("#aab4c2", { metal: true });
    for (let i = 0; i <= 16; i++)
      bars.add(at(cyl(0.025, 0.025, H, st, 10), -W / 2 + i * (W / 16), H / 2, 0));
    for (const y of [0.1, H - 0.1]) {
      bars.add(at(box(W, 0.1, 0.08, st), 0, y, 0));
    }
    // crater (radial impact decal + rim chunks + dust)
    K.crater = new THREE.Group();
    g.add(K.crater);
    const craterTex = canvasTex(512, 512, (c, w, h) => {
      c.clearRect(0, 0, w, h);
      const gr = c.createRadialGradient(w / 2, h / 2, 10, w / 2, h / 2, w / 2);
      gr.addColorStop(0, "#7a5a6e");
      gr.addColorStop(0.55, "#b58aa2");
      gr.addColorStop(0.9, "rgba(230,190,210,0.6)");
      gr.addColorStop(1, "rgba(230,190,210,0)");
      c.fillStyle = gr;
      c.beginPath();
      c.arc(w / 2, h / 2, w / 2, 0, Math.PI * 2);
      c.fill();
      c.strokeStyle = INK;
      c.lineCap = "round";
      c.lineWidth = 5;
      for (let i = 0; i < 14; i++) {
        const a = (i / 14) * Math.PI * 2 + hash(i) * 0.3;
        let x = w / 2,
          y = h / 2,
          r = 24;
        c.beginPath();
        c.moveTo(x, y);
        while (r < w * (0.28 + hash(i + 5) * 0.2)) {
          r += 28 + hash(i * 7 + r) * 20;
          const aa = a + (hash(i + r) - 0.5) * 0.5;
          x = w / 2 + Math.cos(aa) * r;
          y = h / 2 + Math.sin(aa) * r;
          c.lineTo(x, y);
        }
        c.stroke();
      }
      c.lineWidth = 4;
      c.beginPath();
      c.arc(w / 2, h / 2, w * 0.2, 0.2, 2.6);
      c.stroke();
      c.beginPath();
      c.arc(w / 2, h / 2, w * 0.33, 3.4, 5.6);
      c.stroke();
    });
    const disc = new THREE.Mesh(
      new THREE.CircleGeometry(1.0, 48),
      new THREE.MeshBasicMaterial({ map: craterTex, transparent: true, depthWrite: false })
    );
    disc.rotation.x = -Math.PI / 2;
    disc.position.y = 0.012;
    K.crater.add(disc);
    K.disc = disc;
    K.chunks = new THREE.Group();
    g.add(K.chunks);
    for (let i = 0; i < 12; i++)
      K.chunks.add(
        new THREE.Mesh(
          new THREE.DodecahedronGeometry(0.05 + hash(i) * 0.05),
          solid(i % 2 ? "#e7c3d6" : "#d8dde6")
        )
      );
    K.puffs = makePuffs(8);
    g.add(K.puffs);
    // welded bench (+ floor holes it leaves behind)
    const bench = new THREE.Group();
    g.add(bench);
    K.bench = bench;
    const steel = solid(PAL.steel, { metal: true });
    bench.add(at(flatSlab(0.9, 0.42, 0.06, 0.03, steel), 0, 0.45, 0));
    bench.add(at(rbox(0.9, 0.44, 0.06, 0.03, steel), 0, 0.22, 0.21));
    for (const x of [-0.4, 0.4])
      bench.add(at(rbox(0.06, 0.44, 0.38, 0.02, steel), x, 0.22, 0));
    bench.add(at(rim(0.03, 0.01, steel), 0, 0.5, 0.21)); // keeps the seat lip rolled
    K.welds = [
      [-0.4, -0.17],
      [0.4, -0.17],
      [-0.4, 0.17],
      [0.4, 0.17],
    ].map(([x, z]) => {
      const w = new THREE.Mesh(new THREE.TorusGeometry(0.05, 0.015, 8, 20), solid(PAL.orange));
      w.rotation.x = Math.PI / 2;
      w.position.set(x, 0.015, z);
      bench.add(w);
      return w;
    });
    K.holes = new THREE.Group();
    g.add(K.holes);
    for (const [x, z] of [
      [-0.4, -0.17],
      [0.4, -0.17],
      [-0.4, 0.17],
      [0.4, 0.17],
    ]) {
      const h = new THREE.Mesh(new THREE.CircleGeometry(0.07, 16), solid("#6b4a5c"));
      h.rotation.x = -Math.PI / 2;
      h.position.set(x, 0.013, z);
      K.holes.add(h);
    }
    // knitted pink scarf + yarn ball + strand
    const knit = canvasTex(256, 64, (c, w, h) => {
      c.fillStyle = PAL.pink;
      c.fillRect(0, 0, w, h);
      c.strokeStyle = "#ffb3d4";
      c.lineWidth = 4;
      c.lineCap = "round";
      for (let x = 0; x < w; x += 16)
        for (let y = 4; y < h; y += 16) {
          c.beginPath();
          c.moveTo(x, y);
          c.lineTo(x + 8, y + 10);
          c.lineTo(x + 16, y);
          c.stroke();
        }
      c.fillStyle = "#ffffff";
      c.fillRect(0, 22, w, 6);
      c.fillRect(0, 40, w, 6);
      c.strokeStyle = INK;
      c.lineWidth = 4;
      c.strokeRect(0, 0, w, h);
    });
    K.scarf = new Ribbon(28, 0.2, makeMaterial(knit as any, {} as any) as THREE.Material);
    g.add(K.scarf.mesh);
    const yarnTex = canvasTex(256, 128, (c, w, h) => {
      c.fillStyle = PAL.pink;
      c.fillRect(0, 0, w, h);
      c.strokeStyle = "#ffb3d4";
      c.lineWidth = 6;
      c.lineCap = "round";
      for (let i = -2; i < 14; i++) {
        c.beginPath();
        c.moveTo(i * 24, h);
        c.quadraticCurveTo(i * 24 + 40, h / 2, i * 24 + 10, 0);
        c.stroke();
      }
      c.strokeStyle = INK;
      c.lineWidth = 3;
      for (let i = 0; i < 5; i++) {
        c.beginPath();
        c.moveTo(0, 14 + i * 24);
        c.quadraticCurveTo(w / 2, 40 + i * 20, w, 14 + i * 24);
        c.stroke();
      }
    });
    K.yarn = new THREE.Mesh(
      new THREE.SphereGeometry(0.09, 24, 16),
      makeMaterial(yarnTex as any, {} as any) as THREE.Material
    );
    g.add(K.yarn);
    K.strand = unitCyl(0.008, solid(PAL.pink));
    g.add(K.strand);
    K.swatch = at(swatchFan(), 0.22, 1.25, 0.0);
    g.add(K.swatch);
    return g;
  }

  private buildPod() {
    const g = new THREE.Group(),
      P = this.P,
      steel = solid(PAL.steel, { metal: true });
    g.add(at(box(8, 0.1, 5, surf("tiles", tiles, 6, 4)), 0, -0.05, -0.5));
    g.add(at(box(8, 5, 0.1, surf("cinder", cinderblock, 6, 3)), 0, 2.5, -1.9));
    // lower-tier cell doors
    for (let i = 0; i < 5; i++) {
      g.add(
        at(
          rbox(0.8, 1.9, 0.06, 0.03, surf("plates", metalPlates, 1, 1)),
          -2.4 + i * 1.2,
          0.95,
          -1.82
        )
      );
      g.add(
        at(rbox(0.3, 0.2, 0.04, 0.03, solid("#3a2a40")), -2.4 + i * 1.2, 1.5, -1.78)
      );
    }
    // upper tier catwalk: deck, fascia, railing with rolled caps, stairs, upper doors
    g.add(at(box(8, 0.12, 0.9, surf("plates", metalPlates, 5, 1)), 0, 2.2, -1.4));
    g.add(at(rbox(8, 0.25, 0.08, 0.03, solid("#8fa0b8", { metal: true })), 0, 2.05, -0.95));
    for (let i = 0; i < 21; i++)
      g.add(at(cyl(0.02, 0.02, 0.9, steel, 8), -3.9 + i * 0.39, 2.7, -0.97));
    const topRail = cyl(0.035, 0.035, 8, steel, 12);
    topRail.rotation.z = Math.PI / 2;
    g.add(at(topRail, 0, 3.15, -0.97));
    for (const x of [-4, 4]) g.add(at(ball(0.05, steel), x, 3.15, -0.97));
    for (let i = 0; i < 8; i++)
      g.add(at(box(0.6, 0.06, 0.6, steel), -3.2 - i * 0.2, i * 0.27, -1.2 + 0 * i));
    for (let i = 0; i < 5; i++)
      g.add(
        at(
          rbox(0.8, 1.9, 0.06, 0.03, surf("plates", metalPlates, 1, 1)),
          -2.4 + i * 1.2,
          3.2,
          -1.82
        )
      );
    // blue picnic table (long axis = z), two benches, A-frame legs
    const blue = solid(PAL.blue),
      table = new THREE.Group();
    g.add(table);
    table.add(at(flatSlab(0.9, 1.8, 0.08, 0.03, blue), 0, 0.78, 0));
    for (const x of [-0.62, 0.62])
      table.add(at(flatSlab(0.28, 1.8, 0.06, 0.02, blue), x, 0.45, 0));
    for (const z of [-0.6, 0.6])
      for (const s of [-1, 1]) {
        const l = box(0.07, 0.95, 0.07, blue);
        l.position.set(s * 0.32, 0.4, z);
        l.rotation.z = -s * 0.32;
        table.add(l);
      }
    // lunch trays (rolled rims via bevelled slab) + food blobs
    P.trays = [
      [-0.2, -0.5],
      [0.2, -0.5],
      [-0.2, 0.5],
      [0.2, 0.5],
    ].map(([x, z], i) => {
      const t = new THREE.Group();
      t.add(at(flatSlab(0.3, 0.22, 0.03, 0.03, solid(PAL.tin, { metal: true })), 0, 0, 0));
      t.add(at(ball(0.04, solid(PAL.green)), -0.07, 0.03, 0));
      t.add(at(ball(0.045, solid(PAL.orange)), 0.06, 0.03, 0.03));
      t.add(at(ball(0.03, solid(PAL.red)), 0.0, 0.03, -0.06));
      t.userData.base = [x, 0.8, z];
      t.position.set(x, 0.8, z);
      table.add(t);
      return t;
    });
    // clasped forearms (rigid bar, pivot at table centre) — rotates for the slam
    P.lock = new THREE.Group();
    P.lock.position.set(0, 0.84, 0);
    g.add(P.lock);
    const sleeve = solid(PAL.orange);
    for (const s of [-1, 1]) {
      const a = cyl(0.045, 0.045, 0.42, sleeve, 12);
      a.position.set(s * 0.035, 0.2, 0);
      a.rotation.z = -s * 0.16;
      P.lock.add(a);
      P.lock.add(at(ball(0.05, sleeve), s * 0.11, 0.0, 0));
    }
    P.lock.add(at(ball(0.07, solid(PAL.skin)), 0, 0.43, 0));
    P.star = at(impactStar(0.3), -0.18, 0.95, 0.15);
    g.add(P.star);
    P.puffs = makePuffs(8);
    g.add(P.puffs);
    return g;
  }

  private buildStation() {
    const g = new THREE.Group(),
      S = this.S,
      wood = surf("planks", planks, 2, 1);
    g.add(at(box(6, 0.1, 4, surf("planks", planks, 4, 3)), 0, -0.05, 0));
    g.add(at(box(6, 3.6, 0.1, surf("brick", brick, 4, 2)), 0, 1.8, -1.0));
    // night window with a moon (flat glow discs) behind the clock's left
    g.add(at(box(0.9, 1.1, 0.06, solid("#1f2a5a")), -1.1, 1.8, -0.93));
    g.add(at(new THREE.Mesh(new THREE.CircleGeometry(0.2, 32), glow(PAL.moon)), -1.1, 1.95, -0.89));
    for (const [w, h, x, y] of [
      [1.0, 0.06, 0, 0.58],
      [1.0, 0.06, 0, -0.58],
      [0.06, 1.2, -0.48, 0],
      [0.06, 1.2, 0.48, 0],
      [0.04, 1.1, 0, 0],
    ])
      g.add(at(box(w, h, 0.07, solid(PAL.white)), -1.1 + x, 1.8 + y, -0.88));
    // guard desk with rolled front lip, mug, key ring, desk lamp
    const desk = new THREE.Group();
    g.add(desk);
    desk.add(at(flatSlab(1.5, 0.7, 0.07, 0.03, wood), 0, 0.9, 0.05));
    desk.add(at(rbox(1.5, 0.86, 0.06, 0.03, wood), 0, 0.43, 0.38));
    const lip = cyl(0.04, 0.04, 1.5, wood, 20);
    lip.rotation.z = Math.PI / 2;
    desk.add(at(lip, 0, 0.9, 0.4));
    const mug = new THREE.Group();
    mug.add(at(cyl(0.05, 0.045, 0.1, solid(PAL.red)), 0, 0.05, 0));
    mug.add(at(rim(0.05, 0.008, solid(PAL.red)), 0, 0.1, 0));
    const h = new THREE.Mesh(new THREE.TorusGeometry(0.03, 0.01, 8, 16), solid(PAL.red));
    h.position.set(0.06, 0.05, 0);
    mug.add(h);
    mug.position.set(0.35, 0.94, 0.15);
    desk.add(mug);
    const kr = new THREE.Mesh(
      new THREE.TorusGeometry(0.05, 0.008, 8, 24),
      solid(PAL.brass, { metal: true })
    );
    kr.position.set(-0.4, 0.96, 0.2);
    kr.rotation.x = Math.PI / 2;
    desk.add(kr);
    // wall clock (rolled rim, tick bars, two hands — no numerals)
    const clock = new THREE.Group();
    clock.position.set(0.15, 2.05, -0.92);
    g.add(clock);
    clock.add(new THREE.Mesh(new THREE.CircleGeometry(0.34, 48), solid(PAL.white)));
    clock.add(
      at(
        new THREE.Mesh(
          new THREE.TorusGeometry(0.34, 0.04, 12, 48),
          solid(PAL.brass, { metal: true })
        ),
        0,
        0,
        0.02
      )
    );
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * Math.PI * 2,
        t = box(0.02, i % 3 ? 0.04 : 0.07, 0.01, solid(INK));
      t.position.set(Math.sin(a) * 0.27, Math.cos(a) * 0.27, 0.015);
      t.rotation.z = -a;
      clock.add(t);
    }
    S.hour = new THREE.Group();
    S.hour.add(at(box(0.03, 0.17, 0.012, solid(INK)), 0, 0.075, 0.03));
    clock.add(S.hour);
    S.min = new THREE.Group();
    S.min.add(at(box(0.02, 0.26, 0.012, solid(INK)), 0, 0.12, 0.04));
    clock.add(S.min);
    clock.add(at(ball(0.025, solid(INK)), 0, 0, 0.04));
    S.bubbles = [0, 1, 2].map(() => {
      const b = ball(0.07, glow("#e7f1ff", 0.85));
      g.add(b);
      return b;
    });
    return g;
  }

  private buildClassroom() {
    const g = new THREE.Group(),
      B = this.B,
      wood = surf("planks", planks, 2, 1);
    g.add(at(box(6, 0.1, 4, surf("planks", planks, 4, 3)), 0, -0.05, 0));
    g.add(at(box(6, 3.2, 0.1, solid("#ffe9b8")), 0, 1.6, -0.75));
    // blackboard with wooden frame + chalk tray (chalk sticks + eraser)
    const bw = 1.9,
      bh = 1.15,
      by = 1.55;
    g.add(at(rbox(bw + 0.18, bh + 0.18, 0.06, 0.04, wood), 0, by, -0.66));
    B.canvas = document.createElement("canvas");
    B.canvas.width = 1024;
    B.canvas.height = 620;
    B.tex = new THREE.CanvasTexture(B.canvas);
    B.tex.colorSpace = THREE.SRGBColorSpace;
    B.tex.anisotropy = 8;
    g.add(
      at(
        new THREE.Mesh(new THREE.PlaneGeometry(bw, bh), new THREE.MeshBasicMaterial({ map: B.tex })),
        0,
        by,
        -0.625
      )
    );
    g.add(at(box(bw + 0.1, 0.05, 0.1, wood), 0, by - bh / 2 - 0.1, -0.6));
    for (let i = 0; i < 3; i++)
      g.add(
        at(
          cyl(0.012, 0.012, 0.07, solid(PAL.chalk), 8),
          -0.5 + i * 0.07,
          by - bh / 2 - 0.06,
          -0.58
        )
      ).rotation.z = Math.PI / 2;
    g.add(at(rbox(0.12, 0.05, 0.04, 0.01, solid(PAL.orange)), 0.4, by - bh / 2 - 0.06, -0.58));
    B.board = { w: bw, h: bh, y: by, z: -0.62 };
    B.pointer = unitCyl(0.011, solid(PAL.brass));
    g.add(B.pointer);
    B.tip = ball(0.022, solid(PAL.red));
    g.add(B.tip);
    B.last = -1;
    return g;
  }

  private buildYard() {
    const g = new THREE.Group(),
      Y = this.Y;
    g.add(at(box(8, 0.1, 6, surf("stone", stone, 5, 4)), 0, -0.05, 0));
    g.add(at(box(8, 4, 0.1, surf("cinder", cinderblock, 6, 3)), 0, 2, -1.3));
    // three wipe panels
    Y.panels = [-0.62, 0, 0.62].map((x) => {
      const p = wipePanel(0.56, 1.7, solid(PAL.pink), true);
      p.position.set(x - 0.28, 1.0, -1.24);
      g.add(p);
      g.add(at(rbox(0.6, 1.74, 0.02, 0.03, solid(INK)), x, 1.0, -1.255));
      return { mesh: p, x };
    });
    // box truck (right edge): body, cab, rolled wheel rims, can pyramid at the open back
    const truck = new THREE.Group();
    truck.position.set(1.55, 0, -0.6);
    g.add(truck);
    truck.add(at(rbox(1.3, 1.2, 1.1, 0.06, solid(PAL.white)), 0, 0.85, 0));
    truck.add(at(rbox(0.6, 0.85, 1.0, 0.06, solid(PAL.blue)), 0.95, 0.65, 0));
    for (const x of [-0.4, 0.4, 1.0])
      for (const z of [-0.5, 0.5]) {
        const w = cyl(0.2, 0.2, 0.12, solid(INK), 24);
        w.rotation.x = Math.PI / 2;
        truck.add(at(w, x, 0.2, z));
        const r = new THREE.Mesh(
          new THREE.TorusGeometry(0.2, 0.025, 8, 24),
          solid(PAL.steel, { metal: true })
        );
        r.position.set(x, 0.2, z * 1.12);
        truck.add(r);
      }
    [
      [0, 0],
      [0.18, 0],
      [0.09, 0.2],
    ].forEach(([x, y], i) =>
      truck.add(
        at(
          paintCan(0.08, 0.15, PAL.pink, solid(PAL.pink)),
          -0.68 + x,
          0.28 + y,
          0.35 - i * 0.05
        )
      )
    );
    // can pyramid in the foreground-left
    const pile = new THREE.Group();
    pile.position.set(-1.0, 0, 0.3);
    g.add(pile);
    [
      [-0.2, 0],
      [0, 0],
      [0.2, 0],
      [-0.1, 0.15],
      [0.1, 0.15],
      [0, 0.3],
    ].forEach(([x, y]) =>
      pile.add(at(paintCan(0.09, 0.14, PAL.pink, solid(PAL.pink)), x, y, 0))
    );
    return g;
  }

  /* ════════════════════════════ PER-FRAME UPDATE ═══════════════════════════ */

  /** Poses the world for `frame`; returns the exact 3D autofocus point (world metres). */
  update(frame: number, camera: THREE.PerspectiveCamera): THREE.Vector3 {
    const shot = shotAt(frame),
      t = frame - shot.a,
      n = shot.b - shot.a,
      st = shot.stage;

    // Update lighting rig per shot preset
    const lp = LIGHTS[shot.light];
    this.dirLight.intensity = lp.sunI;
    this.dirLight.color.set(lp.sunCol);
    this.hemiLight.intensity = lp.hemiI;
    this.hemiLight.color.set(lp.sky);
    this.hemiLight.groundColor.set(lp.ground);

    const radAz = (lp.az * Math.PI) / 180;
    const radEl = (lp.el * Math.PI) / 180;
    const dist = 10;
    this.dirLight.position.set(
      camera.position.x + dist * Math.cos(radEl) * Math.sin(radAz),
      camera.position.y + dist * Math.sin(radEl),
      camera.position.z + dist * Math.cos(radEl) * Math.cos(radAz)
    );
    this.dirLight.target.position.copy(camera.position);
    this.dirLight.target.updateMatrixWorld();

    for (const id of Object.keys(this.sets) as SetId[]) this.sets[id].visible = false; // anti-bleed: hideAll()
    this.sets[SET_OF[st]].visible = true;
    this.actors.forEach((a) => (a.node.visible = false));

    // interior cell shots must never see the front bars
    const bars = this.sets.cell.getObjectByName("frontBars");
    if (bars) bars.visible = BARS_VISIBLE.has(st);

    switch (st) {
      case "corridor":
        this.sCorridor(t);
        break;
      case "mix_bench":
        this.sMix(t);
        break;
      case "paint_wall":
        this.sPaintWall(t);
        break;
      case "guards_corridor":
        this.sGuards(t);
        break;
      case "stopwatch_rule":
        this.sRule(t);
        break;
      case "cell_door":
        this.sDoor(t);
        break;
      case "pink_cell_inmate":
        this.sLanding(t);
        break;
      case "door_exit":
        this.sExit(t, n);
        break;
      case "arm_wrestle":
        this.sArm(t);
        break;
      case "reaction":
        this.sReaction(t);
        break;
      case "truckload_montage":
        this.sTruck(t);
        break;
      case "night_station":
        this.sStation(t, n);
        break;
      case "night_quiet":
        this.sQuiet(t);
        break;
      case "night_pacing":
        this.sPacing(t, n);
        break;
      case "bench_rage":
        this.sRage(t);
        break;
      case "blackboard_chart":
        this.sBoard(t);
        break;
      case "rage_payoff":
        this.sPayoff(t);
        break;
    }
    this.actors.forEach((a) => {
      if (a.node.visible) a.node.faceCamera(camera);
    });

    // dev guard: SKILL.md hard rule — camera < 1.8 m from the subject is forbidden
    if (!this.warned.has(shot.id) && camera.position.distanceTo(this.focus) < 1.8) {
      this.warned.add(shot.id);
      console.warn(
        `[pink-world] shot ${shot.id} (${st}): camera ${camera.position.distanceTo(this.focus).toFixed(2)} m from focus (< 1.8 m).`
      );
    }
    return this.focus.clone();
  }

  /* ── corridor set ───────────────────────────────────────────────────────── */
  private corridorReset(doorPos: V3 = [0, 0, -3.2], open = 0) {
    const C = this.C;
    C.door.group.position.set(...doorPos);
    C.door.pivot.rotation.y = -open;
    C.bucket.visible = false;
    C.watch.visible = false;
    C.qm.visible = false;
    C.splats.visible = false;
    C.drops.forEach((d: THREE.Mesh) => (d.visible = false));
  }
  private sCorridor(t: number) {
    const C = this.C;
    this.corridorReset([0, 0, -3.2], 0);
    C.splats.visible = true;
    C.splats.children.forEach((s: THREE.Object3D, i: number) => (s.visible = t > i * 12));
    C.lamps.forEach(
      (l: THREE.Group, i: number) => (l.userData.bulb.visible = !(i === 1 && t % 23 > 19))
    ); // one flickering bulb
    const sz = lerp(-1.4, 0.2, ease(t / 101)),
      gz = lerp(-1.9, -0.2, ease(t / 101));
    this.setActorSpec(
      "scientist",
      { ...SCI, holdingProp: "clipboard" },
      [0.32, 0.02 * Math.abs(Math.sin(t * 0.5)), sz]
    );
    this.setActorSpec(
      "guardB",
      { ...GUARD_B, holdingProp: "paint_roller" },
      [-0.3, 0.02 * Math.abs(Math.sin(t * 0.5 + 1)), gz]
    );
    this.focus.set(0.32, FACE, sz);
  }
  private sGuards(t: number) {
    const C = this.C;
    this.corridorReset([0, 0, -3.2], 0);
    C.bucket.visible = true;
    C.bucket.position.set(0.05, 0, 0.45);
    this.setActorSpec(
      "guardA",
      { ...GUARD_A, expression: "smile" },
      [-0.28, 0.015 * Math.sin(t * 0.3), 0]
    );
    this.setActorSpec(
      "guardB",
      { ...GUARD_B, expression: t > 40 ? "scheming" : "smile" },
      [0.3, 0.015 * Math.sin(t * 0.3 + 2), -0.12]
    );
    this.focus.set(0.0, FACE, -0.06);
  }
  private sRule(t: number) {
    const C = this.C;
    this.corridorReset([0, 0, -3.2], 0);
    C.watch.visible = true;
    C.watch.position.set(0.45, 1.5, -0.35);
    C.watch.scale.setScalar(Math.max(0.01, backOut(t / 12)));
    setWedge(C.watch, clamp01(t / 60) * 0.25 + 0.02);
    this.setActorSpec(
      "scientist",
      { ...SCI, expression: "speaking", holdingProp: "stopwatch" },
      [0, 0, 0]
    );
    this.setActorSpec("guardB", { ...GUARD_B, expression: "deadpan" }, [-0.55, 0, -0.6]);
    this.focus.set(0, FACE, 0);
  }
  private sDoor(t: number) {
    const C = this.C,
      open = ease((t - 130) / 36) * 1.2;
    this.corridorReset([0, 0, -0.2], open);
    C.door.keys.rotation.z = 0.12 * Math.sin(t * 0.25);
    this.setActorSpec(
      "guardA",
      { ...GUARD_A, expression: "scheming", holdingProp: "stopwatch" },
      [0.3, 0, 0.55]
    );
    // focus: guard's face, drifting to the door window as it opens
    const k = ease((t - 110) / 30);
    this.focus.set(lerp(0.3, 0, k), lerp(FACE, 1.65, k), lerp(0.55, -0.15, k));
  }
  private sExit(t: number, n: number) {
    this.corridorReset([0, 0, -0.2], 1.9);
    const e = ease(t / (n - 1)),
      z = lerp(-0.45, 0.35, e);
    this.setActorSpec(
      "inmate",
      { ...BIG, expression: e > 0.6 ? "smile" : "deadpan" },
      [0, 0.02 * Math.abs(Math.sin(t * 0.4)), z]
    );
    this.setActorSpec("guardA", { ...GUARD_A, expression: "deadpan" }, [-0.55, 0, 0.1]);
    this.setActorSpec("guardB", { ...GUARD_B, expression: "smile" }, [0.55, 0, 0.1]);
    this.focus.set(0, FACE, z);
  }
  private sReaction(t: number) {
    const C = this.C;
    this.corridorReset([0, 0, -3.2], 0);
    const pop = backOut((t - 8) / 10);
    C.qm.visible = t > 8;
    C.qm.position.set(0, 2.0 + 0.03 * Math.sin(t * 0.3), 0.1);
    C.qm.scale.setScalar(Math.max(0.01, pop) * 1.4);
    C.qm.rotation.z = 0.12 * Math.sin(t * 0.2);
    C.drops.forEach((d: THREE.Mesh, i: number) => {
      d.visible = t > 12;
      const k = ((t - 12 + i * 9) % 27) / 27;
      d.position.set(-0.45 + i * 0.12, 2.0 - k * 0.45, 0.2);
      d.scale.setScalar(1 - k * 0.5);
    });
    this.setActorSpec(
      "guardA",
      { ...GUARD_A, expression: "shocked" },
      [-0.22, 0, 0],
      { scale: 1 + 0.02 * Math.sin(t * 0.8) }
    );
    this.setActorSpec(
      "scientist",
      { ...SCI, expression: "shocked", holdingProp: "clipboard" },
      [0.24, 0, 0.04]
    );
    this.focus.set(0, FACE, 0);
  }

  /* ── lab ────────────────────────────────────────────────────────────────── */
  private sMix(t: number) {
    const L = this.L,
      p = ease((t - 8) / 22),
      pourOn = t > 22 && t < 82;
    // sunbeam shimmer + deterministic dust motes
    L.beams.forEach((b: THREE.Group, i: number) =>
      b.children.forEach(
        (c) =>
          (((c as THREE.Mesh).material as THREE.MeshBasicMaterial).opacity =
            0.42 + 0.1 * Math.sin(t * 0.07 + i))
      )
    );
    for (let i = 0; i < 36; i++) {
      const u = hash(i),
        k = (u + t * 0.0025 * (0.5 + hash(i + 1))) % 1;
      L.motePos.set(
        [
          lerp(-1.0, 0.15, k) + Math.sin(t * 0.02 + i) * 0.05,
          lerp(2.0, 0.95, k) + Math.cos(t * 0.017 + i) * 0.04,
          lerp(-1.1, 0.15, k) + hash(i + 7) * 0.1,
        ],
        i * 3
      );
    }
    L.motes.geometry.attributes.position.needsUpdate = true;
    // pint tips over the can; red stream; paint turns white → pink
    L.pint.position.set(0.2, 1.52, 0.05);
    L.pint.rotation.z = p * 2.0;
    const mouth = new THREE.Vector3(
        0.2 - 0.09 * Math.sin(p * 2.0),
        1.52 + 0.09 * Math.cos(p * 2.0),
        0.05
      ),
      target = new THREE.Vector3(0, 1.2, 0.05);
    L.stream.visible = pourOn;
    if (pourOn) {
      stretch(L.stream, mouth, target);
      L.stream.scale.x = 1 + 0.2 * Math.sin(t * 0.8);
    }
    L.splash.visible = pourOn;
    L.splash.scale.setScalar(1 + 0.3 * Math.sin(t * 0.9));
    (L.paintMat as any).color?.lerpColors(
      new THREE.Color(PAL.white),
      new THREE.Color(PAL.pink),
      ease((t - 25) / 60)
    );
    L.bar.scale.x = Math.max(0.05, ease((t - 22) / 60));
    L.bar.position.x = -0.085 * (1 - L.bar.scale.x);
    const stir = t > 84;
    L.stick.visible = stir;
    L.stick.position.set(
      Math.cos(t * 0.4) * 0.04,
      1.34,
      0.05 + Math.sin(t * 0.4) * 0.04
    );
    L.stick.rotation.z = Math.cos(t * 0.4) * 0.2;
    L.beaker.userData.liquid.scale.y = 0.9 + 0.1 * Math.sin(t * 0.2);
    this.setActorSpec(
      "scientist",
      { ...SCI, expression: t < 30 ? "scheming" : "smile" },
      [0.05, 0, -0.55]
    );
    this.focus.set(0.05, 1.2, 0.05); // can mouth / pour point
  }

  /* ── cell ───────────────────────────────────────────────────────────────── */
  private cellReset(opts: { bench?: V3 | null; repaint?: boolean }) {
    const K = this.K;
    K.bench.visible = !!opts.bench;
    if (opts.bench) {
      K.bench.position.set(...opts.bench);
      K.bench.rotation.set(0, 0, 0);
    }
    K.holes.visible = false;
    K.chunks.visible = false;
    K.crater.visible = false;
    K.puffs.visible = false;
    K.swatch.visible = false;
    K.scarf.mesh.visible = false;
    K.yarn.visible = false;
    K.strand.visible = false;
    K.welds.forEach((w: THREE.Mesh) => (w.visible = true));
    if (!opts.repaint) {
      setWipe(K.wrong, 0);
      setWipe(K.right, 1);
    }
  }
  private launchChunks(origin: V3, s: number, power: number) {
    const K = this.K;
    K.chunks.visible = s >= 0 && s < 60;
    K.chunks.children.forEach((c: THREE.Object3D, i: number) => {
      const a = (i / 12) * Math.PI * 2 + hash(i) * 0.5,
        r = 0.55 + hash(i + 2) * 0.3,
        y = Math.max(0, 0.11 * power * s - 0.0042 * s * s);
      c.position.set(
        origin[0] + Math.cos(a) * r * (1 + 0.02 * Math.min(s, 22)),
        origin[1] + 0.05 + y,
        origin[2] + Math.sin(a) * r * (1 + 0.02 * Math.min(s, 22))
      );
      c.rotation.set(s * 0.2 * (i % 3), s * 0.15, s * 0.1);
    });
  }
  private sPaintWall(t: number) {
    const K = this.K;
    this.cellReset({ bench: null, repaint: true });
    const p1 = ease(t / 32),
      p2 = ease((t - 70) / 38);
    const px = t < 70 ? lerp(-0.5, 0.1, p1) : lerp(0.1, -0.5, p2);
    const wf = t < 32 ? px + 0.18 : lerp(0.28, 1.6, ease((t - 32) / 12));
    const rf = t < 108 ? px - 0.18 : lerp(-0.68, -1.6, clamp01((t - 108) / 10));
    setWipe(K.wrong, (wf + 1.6) / 3.2);
    setWipe(K.right, t < 70 ? 0 : (1.6 - rf) / 3.2);
    K.swatch.visible = t > 34 && t < 72;
    K.swatch.scale.setScalar(Math.max(0.01, backOut((t - 34) / 8)) * 1.3);
    K.swatch.rotation.z = -0.15 + 0.05 * Math.sin(t * 0.3);
    this.setActorSpec(
      "guardB",
      { ...GUARD_B, expression: "deadpan", holdingProp: "paint_roller" },
      [px, 0, -0.62]
    );
    this.setActorSpec(
      "scientist",
      {
        ...SCI,
        expression: t < 34 ? "scheming" : t < 70 ? "shocked" : "smile",
        holdingProp: undefined,
      },
      [0.42, 0, -0.1]
    );
    const w = ease((t - 30) / 8) * (1 - ease((t - 66) / 8)); // 0 = painter, 1 = swatch
    this.focus.set(lerp(px, 0.22, w), lerp(1.5, 1.3, w), lerp(-0.62, 0, w));
  }
  private sLanding(t: number) {
    const K = this.K;
    this.cellReset({ bench: null });
    const s = t - 26,
      fall = clamp01((t - 8) / 18);
    const y =
      t < 26
        ? lerp(2.6, 0, fall * fall)
        : 0.07 * Math.abs(Math.sin(s * 0.32)) * Math.exp(-s / 9);
    K.crater.visible = s >= 0;
    K.crater.scale.setScalar(Math.max(0.01, backOut(s / 7)));
    this.launchChunks([0, 0, 0], s, 1);
    animatePuffs(K.puffs, s, [0, 0, 0], 0.9);
    K.puffs.visible = s >= 0 && s < 36;
    this.setActorSpec("inmate", { ...BIG, expression: "smile" }, [0, y, 0], {
      scale: 1 + 0.018 * Math.sin(t * 1.5),
      rotZ: t > 30 ? 0.03 * Math.sin(t * 1.1) : 0,
    });
    this.focus.set(0, y + FACE, 0);
  }
  private sQuiet(t: number) {
    const K = this.K;
    this.cellReset({ bench: [0.35, 0, 0.65] });
    K.scarf.mesh.visible = true;
    K.yarn.visible = true;
    K.scarf.set((u: number): V3 => [
      0.35 - 0.42 + 0.84 * u,
      0.58 - 0.15 * Math.sin(Math.PI * u) + 0.01 * Math.sin(t * 0.1 + u * 6),
      0.7,
    ]);
    K.yarn.position.set(0.62, 0.54, 0.62);
    K.yarn.rotation.z = t * 0.01;
    this.setActorSpec("inmate", { ...BIG, expression: "deadpan" }, [
      0.35,
      -0.4 + 0.008 * Math.sin(t * 0.15),
      0.35,
    ]); // seated: lower body hidden by the bench front plate
    this.focus.set(0.35, FACE - 0.4, 0.35);
  }
  private sPacing(t: number, n: number) {
    const K = this.K;
    this.cellReset({ bench: [1.1, 0, 0.0] });
    const e = ease(t / (n - 1)),
      ix = lerp(-0.4, 0.4, e),
      bob = 0.03 * Math.abs(Math.sin(t * 0.9));
    K.scarf.mesh.visible = true;
    K.yarn.visible = true;
    K.strand.visible = true;
    K.scarf.set((u: number): V3 => [
      ix - 0.1 - u * 0.8,
      1.35 - 0.75 * u + 0.05 * Math.sin(t * 0.3 + u * 8),
      0.4,
    ]);
    const yx = ix - 0.8;
    K.yarn.position.set(yx, 0.09, 0.5);
    K.yarn.rotation.z = -yx / 0.09;
    stretch(K.strand, new THREE.Vector3(yx, 0.09, 0.5), new THREE.Vector3(ix, 1.0, 0.4));
    this.setActorSpec("inmate", { ...BIG, expression: "scheming" }, [ix, bob, 0.3]);
    this.focus.set(ix, FACE, 0.3);
  }
  private sRage(t: number) {
    const K = this.K;
    this.cellReset({ bench: [0.35, 0, 0.65] });
    const up = ease(t / 10),
      strain = clamp01((t - 10) / 30),
      lift = ease((t - 40) / 22),
      held = t >= 62;
    const shake = t < 40 ? strain * 0.012 * Math.sin(t * 2.3) : 0;
    const b = K.bench as THREE.Group;
    b.position.set(
      0.35 + shake,
      lift * 0.9 + (held ? 0.04 * Math.sin(t * 0.5) : 0),
      0.65
    );
    b.rotation.x = -0.5 * lift;
    b.rotation.z = held ? 0.05 * Math.sin(t * 0.4) : 0;
    K.holes.visible = t >= 40;
    K.holes.position.set(0.35, 0, 0.65);
    K.welds.forEach((w: THREE.Mesh) => (w.visible = t < 40));
    this.launchChunks([0.35, 0, 0.65], t - 40, 1.2);
    animatePuffs(K.puffs, t - 40, [0.35, 0, 0.65], 0.6);
    K.scarf.mesh.visible = true;
    K.scarf.set((u: number): V3 => [
      0.35 + 0.55 * Math.sin(u * 4.2 - t * 0.25),
      1.9 + 0.5 * u + 0.12 * Math.sin(t * 0.5 + u * 7),
      0.5,
    ]);
    this.setActorSpec(
      "inmate",
      { ...BIG, expression: t < 40 ? "scheming" : "speaking" },
      [0.35, lerp(-0.4, 0, up), 0.35],
      { scale: 1 + 0.08 * ease(t / 60) }
    );
    this.focus.set(0.35, FACE - 0.1, 0.4);
  }
  private sPayoff(t: number) {
    const K = this.K;
    this.cellReset({ bench: null });
    K.holes.visible = true;
    K.holes.position.set(0, 0, 0.65);
    K.scarf.mesh.visible = true;
    K.scarf.set((u: number): V3 => [
      0.55 * Math.sin(u * 4.2 - t * 0.25),
      1.9 + 0.5 * u + 0.12 * Math.sin(t * 0.5 + u * 7),
      0.3,
    ]);
    K.bench.visible = true;
    K.bench.position.set(0, 1.25 + 0.04 * Math.sin(t * 0.3), 0.55);
    K.bench.rotation.set(-0.5, 0, 0.2 * Math.sin(t * 0.2)); // hurled/held in front of him
    this.setActorSpec("inmate", { ...BIG, expression: "speaking" }, [0, 0, 0], {
      scale: 1.12 + 0.01 * Math.sin(t * 0.7),
    });
    this.setActorSpec(
      "scientist",
      { ...SCI, expression: "shocked", holdingProp: "clipboard" },
      [-0.55, 0, -0.3]
    );
    this.focus.set(0, FACE, 0);
  }

  /* ── cafeteria pod ──────────────────────────────────────────────────────── */
  private sArm(t: number) {
    const P = this.P,
      slam = t - 125; // frame 1040 = shot.a 915 + 125 (matches updatePinkCamera shake)
    // rigid clasped arms: strain (big guy winning) → snap to the big guy's side in 4 frames
    const rot =
      t < 110
        ? -0.15 + 0.07 * Math.sin(t * 0.9)
        : t < 125
        ? lerp(-0.15, -0.3, (t - 110) / 15) + 0.06 * Math.sin(t * 2.2)
        : lerp(-0.3, 1.1, easeOut(slam / 4));
    P.lock.rotation.z = rot;
    P.trays.forEach((tr: THREE.Group, i: number) => {
      const b = tr.userData.base as V3,
        hop =
          slam >= 0
            ? 0.12 * Math.max(0, Math.sin(slam * 0.45)) * Math.exp(-slam / 10)
            : 0;
      tr.position.set(b[0], b[1] + hop, b[2]);
      tr.rotation.z =
        slam >= 0
          ? 0.08 * Math.sin(slam * 0.5 + i) * Math.exp(-slam / 12)
          : 0;
    });
    P.star.visible = slam >= 0 && slam < 14;
    P.star.scale.setScalar(
      Math.max(0.01, backOut(slam / 4)) * (1 - clamp01((slam - 8) / 6))
    );
    P.star.rotation.z = 0.2;
    animatePuffs(P.puffs, slam, [-0.18, 0.8, 0.1], 0.5);
    const spectator = slam >= 0 ? "shocked" : "scheming";
    this.setActorSpec(
      "inmate",
      { ...BIG, expression: slam >= 0 ? "shocked" : "deadpan" },
      [-0.58, -0.38, 0],
      { rotZ: slam >= 0 ? 0.14 * easeOut(slam / 4) : 0 }
    );
    this.setActorSpec(
      "inmate2",
      { ...LEAN, expression: slam >= 0 ? "smile" : "scheming" },
      [0.58, -0.38, 0]
    );
    this.setActorSpec(
      "spectA",
      {
        ...GUARD_B,
        outfit: "inmate_orange",
        headwear: "none",
        hair: "curly",
        expression: spectator,
      },
      [-1.1, 0, -0.9]
    );
    this.setActorSpec(
      "spectB",
      {
        ...GUARD_A,
        outfit: "inmate_orange",
        headwear: "none",
        hair: "side_part",
        expression: spectator,
      },
      [1.1, 0, -0.9]
    );
    this.focus.set(0, 0.95, 0);
  }

  /* ── yard (truckload montage) ───────────────────────────────────────────── */
  private sTruck(t: number) {
    const Y = this.Y;
    const ids = ["guardA", "guardB", "scientist"];
    Y.panels.forEach((p: { mesh: THREE.Mesh; x: number }, k: number) => {
      const r = ease((t - k * 18) / 62);
      setWipe(p.mesh, r);
      const px = p.x - 0.28 + r * 0.56;
      const spec: CharacterSpec =
        k === 2
          ? { ...SCI, expression: "smile" }
          : {
              ...(k ? GUARD_B : GUARD_A),
              expression: "smile",
              holdingProp: "paint_roller",
            };
      this.setActorSpec(ids[k], spec, [
        px,
        0.02 * Math.abs(Math.sin(t * 0.6 + k)),
        -0.8,
      ]);
    });
    this.focus.set(0, 1.2, -0.6);
  }

  /* ── night guard station ────────────────────────────────────────────────── */
  private sStation(t: number, n: number) {
    const S = this.S,
      k = t / (n - 1);
    S.min.rotation.z = -k * Math.PI * 2 * 3;
    S.hour.rotation.z = -k * Math.PI * 2 * 0.25;
    S.bubbles.forEach((b: THREE.Mesh, i: number) => {
      const u = (t * 0.012 + i * 0.33) % 1;
      b.position.set(0.3 + 0.05 * Math.sin(u * 9 + i), 1.5 + u * 0.7, -0.3);
      b.scale.setScalar(0.5 + u * 0.9);
    });
    this.setActorSpec(
      "nightGuard",
      { ...GUARD_A, expression: "deadpan" },
      [0, -0.42 + 0.01 * Math.sin(t * 0.12), -0.35],
      { rotZ: 0.1 }
    );
    this.focus.set(0.15, 2.0, -0.9); // the clock
  }

  /* ── blackboard explanation ─────────────────────────────────────────────── */
  private sBoard(t: number) {
    const B = this.B,
      p = clamp01((t - 20) / 150);
    const q = Math.round(p * 160);
    if (q !== B.last) {
      B.last = q;
      this.drawChart(q / 160);
    }
    // pointer follows the curve head (world coords from board-normalised coords)
    const s = Math.min(p, 1),
      nx = lerp(0.16, 0.88, s),
      ny = this.curveY(s),
      bd = B.board;
    const tip = new THREE.Vector3(
      (nx - 0.5) * bd.w,
      bd.y + (0.5 - ny) * bd.h,
      bd.z + 0.04
    );
    stretch(B.pointer, new THREE.Vector3(-0.35, 1.15, -0.1), tip);
    B.tip.position.copy(tip);
    this.setActorSpec(
      "scientist",
      { ...SCI, expression: p < 0.97 ? "speaking" : "smile" },
      [-0.55, 0, -0.25]
    );
    this.focus.copy(tip);
  }
  private curveY(s: number) {
    return lerp(0.78, 0.22, 1 - Math.exp(-3.4 * s));
  } // normalised canvas y (0 top → 1 bottom), falling aggression
  private drawChart(p: number) {
    const B = this.B,
      c: CanvasRenderingContext2D = B.canvas.getContext("2d")!,
      w = 1024,
      h = 620;
    c.fillStyle = PAL.board;
    c.fillRect(0, 0, w, h);
    c.fillStyle = "rgba(255,255,255,0.10)";
    for (let i = 0; i < 6; i++) {
      c.beginPath();
      c.ellipse(
        120 + i * 150,
        300 + (i % 2) * 120,
        110,
        40,
        0.3,
        0,
        Math.PI * 2
      );
      c.fill();
    } // eraser smudges
    const chalk = (draw: () => void, width = 7) => {
      c.lineCap = "round";
      c.lineJoin = "round";
      c.strokeStyle = INK;
      c.lineWidth = width + 3;
      c.save();
      c.translate(2, 3);
      draw();
      c.restore();
      c.strokeStyle = PAL.chalk;
      c.lineWidth = width;
      draw();
    };
    const X0 = 0.16 * w,
      X1 = 0.88 * w,
      Y0 = 0.1 * h,
      Y1 = 0.86 * h;
    chalk(() => {
      c.beginPath();
      c.moveTo(X0, Y0);
      c.lineTo(X0, Y1);
      c.lineTo(X1 + 20, Y1);
      c.stroke();
      c.beginPath();
      c.moveTo(X1 + 20, Y1);
      c.lineTo(X1, Y1 - 12);
      c.moveTo(X1 + 20, Y1);
      c.lineTo(X1, Y1 + 12);
      c.stroke();
    });
    for (let i = 1; i <= 5; i++)
      chalk(() => {
        c.beginPath();
        c.moveTo(X0 + (i * (X1 - X0)) / 5.5, Y1 - 8);
        c.lineTo(X0 + (i * (X1 - X0)) / 5.5, Y1 + 8);
        c.stroke();
      }, 5);
    // pink-cell icon (top left): square + bars, filled pink
    c.fillStyle = PAL.pink;
    c.fillRect(30, 40, 90, 80);
    chalk(() => {
      c.strokeRect(30, 40, 90, 80);
      for (let i = 1; i < 5; i++) {
        c.beginPath();
        c.moveTo(30 + i * 18, 40);
        c.lineTo(30 + i * 18, 120);
        c.stroke();
      }
    }, 5);
    // falling curve up to p
    const pts = 140;
    chalk(() => {
      c.beginPath();
      for (let i = 0; i <= Math.floor(pts * p); i++) {
        const s = i / pts,
          x = lerp(X0, X1, s),
          y =
            Y0 +
            this.curveY(s) * (Y1 - Y0) * 1.0 +
            Math.sin(i * 0.9) * 1.5;
        i ? c.lineTo(x, y) : c.moveTo(x, y);
      }
      c.stroke();
    }, 9);
    // dashed "15 minutes" line + stopwatch icon once the curve passes it
    const sD = 0.5;
    if (p > sD) {
      const x = lerp(X0, X1, sD);
      chalk(() => {
        c.setLineDash([16, 14]);
        c.beginPath();
        c.moveTo(x, Y1);
        c.lineTo(x, Y0 + 40);
        c.stroke();
        c.setLineDash([]);
      }, 5);
      chalk(() => {
        c.beginPath();
        c.arc(x, Y0 + 20, 22, 0, Math.PI * 2);
        c.stroke();
        c.beginPath();
        c.moveTo(x, Y0 + 20);
        c.lineTo(x, Y0 + 6);
        c.moveTo(x - 6, Y0 - 6);
        c.lineTo(x + 6, Y0 - 6);
        c.stroke();
      }, 5);
    }
    // happy face at the end (arcs + dots, no glyphs)
    if (p > 0.97) {
      const fx = X1 - 40,
        fy = Y1 - 150;
      chalk(() => {
        c.beginPath();
        c.arc(fx, fy, 44, 0, Math.PI * 2);
        c.stroke();
        c.beginPath();
        c.arc(fx, fy + 6, 24, 0.15 * Math.PI, 0.85 * Math.PI);
        c.stroke();
        c.beginPath();
        c.arc(fx - 15, fy - 12, 2, 0, 6.3);
        c.arc(fx + 15, fy - 12, 2, 0, 6.3);
        c.stroke();
      }, 6);
    }
    B.tex.needsUpdate = true;
  }
}

/** Two crossed, additive, gradient planes = cheap volumetric sunbeam from→to. */
function sunbeam(from: THREE.Vector3, to: THREE.Vector3, w: number) {
  const len = from.distanceTo(to),
    g = new THREE.Group();
  g.position.copy(from);
  g.lookAt(to);
  const gradTex = canvasTex(4, 64, (c, _w, h) => {
    const gr = c.createLinearGradient(0, 0, 0, h);
    gr.addColorStop(0, "rgba(255,244,200,0)");
    gr.addColorStop(0.25, "rgba(255,244,200,0.5)");
    gr.addColorStop(0.8, "rgba(255,244,200,0.55)");
    gr.addColorStop(1, "rgba(255,244,200,0.15)");
    c.fillStyle = gr;
    c.fillRect(0, 0, 4, h);
  });
  const m = new THREE.MeshBasicMaterial({
    map: gradTex,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide,
    opacity: 0.45,
  });
  for (const r of [0, Math.PI / 2]) {
    const geo = new THREE.PlaneGeometry(w, len);
    geo.rotateX(Math.PI / 2);
    geo.translate(0, 0, len / 2);
    const p = new THREE.Mesh(geo, m.clone());
    p.rotation.z = r;
    g.add(p);
  }
  return g;
}
